    { id = 2381, name = "Plundering the Plunderers", side = "Horde", classes = "Rogue", level = 18, minLevel = 16, xp = 1350, giver = "Wrenix the Wretched", chainStart = 2379, chainStartName = "Zando'zan", giverNpc = 7161, chainGiver = "Shenthul", chainGiverNpc = 3401, turnIn = "Wrenix the Wretched", turnInNpc = 7161, chainStep = 3, named = { { name = "Wrenix's Gizmotronic Apparatus", npc = 7166 } }, loot = { { item = 7968, name = "Southsea Treasure", from = { { name = "Polly", npc = 7168 } } } }, rewards = { 7676 }, chain = { 2379, 2382 }, objective = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.\n\nShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!" },
    { id = 2282, name = "Alther's Mill", side = "Alliance", classes = "Rogue", level = 20, minLevel = 16, xp = 1550, giver = "Lucius", chainStart = 2281, chainStartName = "Redridge Rendezvous", giverNpc = 6966, chainGiver = "Renzik \"The Shiv\"", chainGiverNpc = 6946, turnIn = "Lucius", turnInNpc = 6966, chainStep = 2, loot = { { item = 7871, name = "Token of Thievery", from = { { name = "Lucius's Lockbox", npc = -121264 } } } }, rewards = { 7907 }, chain = { 2281 }, objective = "Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire." },
    { id = 1999, name = "Tools of the Trade", side = "Horde", classes = "Rogue", level = 20, minLevel = 16, xp = 1550, giver = "Mennet Carkad", chainStart = 1998, chainStartName = "Fenwick Thatros", giverNpc = 6467, chainGiver = "Mennet Carkad", chainGiverNpc = 6467, turnIn = "Mennet Carkad", turnInNpc = 6467, chainStep = 2, loot = { { item = 7309, name = "Dalaran Status Report", from = { { name = "Ambermill Strongbox", npc = -103815 } } } }, chain = { 1998 }, objective = "Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity." },
    { id = 2458, name = "Deep Cover", side = "Horde", classes = "Rogue", level = 20, minLevel = 20, xp = 1150, giver = "Shenthul", chainStart = 2460, chainStartName = "The Shattered Salute", giverNpc = 3401, chainGiver = "Shenthul", chainGiverNpc = 3401, turnIn = "Taskmaster Fizzule", turnInNpc = 7233, chainStep = 2, rewards = { 8066 }, chain = { 2460 }, objective = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.\n\nWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.\n\nThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize." },
    { id = 2480, name = "Hinott's Assistance", side = "Horde", classes = "Rogue", level = 20, minLevel = 20, xp = 160, giver = "Serge Hinott", chainStart = 2460, chainStartName = "The Shattered Salute", giverNpc = 2391, chainGiver = "Shenthul", chainGiverNpc = 3401, turnIn = "Serge Hinott", turnInNpc = 2391, chainStep = 5, group = 2842, rewards = { 8095 }, chain = { 2460, 2458, 2478, 2479 }, objective = "Wait for Serge Hinott to complete the cure." },
    { id = 2360, name = "Mathias and the Defias", side = "Alliance", classes = "Rogue", level = 20, minLevel = 20, xp = 390, giver = "Master Mathias Shaw", giverNpc = 332, turnIn = "Agent Kearnen", turnInNpc = 7024, objective = "Travel to Westfall and find Agent Kearnen for your debriefing." },
    { id = 2460, name = "The Shattered Salute", side = "Horde", classes = "Rogue", level = 20, minLevel = 20, xp = 160, giver = "Shenthul", giverNpc = 3401, turnIn = "Shenthul", turnInNpc = 3401, kills = { { name = "Shenthul", npc = 3401 } }, objective = "Perform the Shattered Salute on Shenthul." },
    { id = 2607, name = "The Touch of Zanzil", side = "Alliance", classes = "Rogue", level = 20, minLevel = 20, xp = 0, giver = "Master Mathias Shaw", chainStart = 2360, chainStartName = "Mathias and the Defias", giverNpc = 332, chainGiver = "Master Mathias Shaw", chainGiverNpc = 332, turnIn = "Doc Mixilpixil", turnInNpc = 7207, chainStep = 3, chain = { 2360, 2359 }, objective = "Speak with Doc Mixilpixil in the cellar of the Barracks." },
    { id = 2608, name = "The Touch of Zanzil", side = "Alliance", classes = "Rogue", level = 20, minLevel = 20, xp = 160, giver = "Doc Mixilpixil", chainStart = 2360, chainStartName = "Mathias and the Defias", giverNpc = 7207, chainGiver = "Master Mathias Shaw", chainGiverNpc = 332, turnIn = "Doc Mixilpixil", turnInNpc = 7207, chainStep = 4, chain = { 2360, 2359, 2607 }, objective = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?" },
    { id = 2609, name = "The Touch of Zanzil", side = "Alliance", classes = "Rogue", level = 20, minLevel = 20, xp = 1150, giver = "Doc Mixilpixil", chainStart = 2360, chainStartName = "Mathias and the Defias", giverNpc = 7207, chainGiver = "Master Mathias Shaw", chainGiverNpc = 332, turnIn = "Doc Mixilpixil", turnInNpc = 7207, chainStep = 5, dungeon = "DEADMINES", loot = { { item = 3421, name = "Simple Wildflowers", from = {  } }, { item = 3372, name = "Leaded Vial", from = {  } }, { item = 4371, name = "Bronze Tube", from = { { name = "Box of Assorted Parts" } } }, { item = 8431, name = "Spool of Light Chartreuse Silk Thread", from = { { name = "Spool of Light Chartreuse Silk Thread", npc = -140911 } } } }, rewards = { 8432 }, chain = { 2360, 2359, 2607, 2608 }, objective = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young <fella/lady>." },
    { id = 2359, name = "Klaven's Tower", side = "Alliance", classes = "Rogue", level = 24, minLevel = 20, xp = 1950, giver = "Agent Kearnen", chainStart = 2360, chainStartName = "Mathias and the Defias", giverNpc = 7024, chainGiver = "Master Mathias Shaw", chainGiverNpc = 332, turnIn = "Master Mathias Shaw", turnInNpc = 332, chainStep = 2, group = 2842, named = { { name = "Mathias Shaw", npc = 332 } }, loot = { { item = 7908, name = "Klaven Mortwake's Journal", from = { { name = "Duskwood Chest", npc = -123214 } } }, { item = 7923, name = "Defias Tower Key", from = { { name = "Malformed Defias Drone", npc = 7051 } } } }, rewards = { 18160 }, chain = { 2360 }, objective = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower." },
    { id = 2478, name = "Mission: Possible But Not Probable", side = "Horde", classes = "Rogue", level = 24, minLevel = 20, xp = 1950, giver = "Taskmaster Fizzule", chainStart = 2460, chainStartName = "The Shattered Salute", giverNpc = 7233, chainGiver = "Shenthul", chainGiverNpc = 3401, turnIn = "Shenthul", turnInNpc = 3401, chainStep = 3, kills = { { name = "Mutated Venture Co. Drone", npc = 7310 }, { name = "Venture Co. Lookout", npc = 7307 }, { name = "Venture Co. Patroller", npc = 7308 } }, loot = { { item = 8074, name = "Gallywix's Head", from = { { name = "Grand Foreman Puzik Gallywix", npc = 7288 } } }, { item = 8072, name = "Silixiz's Tower Key", from = { { name = "Foreman Silixiz", npc = 7287 } } }, { item = 8073, name = "Cache of Zanzil's Altered Mixture", from = { { name = "Gallywix's Lockbox", npc = -129127 } } } }, rewards = { 18160 }, chain = { 2460, 2458 }, objective = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.\n\nAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction." },
    { id = 2479, name = "Hinott's Assistance", side = "Horde", classes = "Rogue", level = 26, minLevel = 20, xp = 1050, giver = "Shenthul", chainStart = 2460, chainStartName = "The Shattered Salute", giverNpc = 3401, chainGiver = "Shenthul", chainGiverNpc = 3401, turnIn = "Serge Hinott", turnInNpc = 2391, chainStep = 4, chain = { 2460, 2458, 2478 }, objective = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.\n\nTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!" },
    { id = 96779, name = "Syndicate Sabotage", classes = "Rogue", level = 24, minLevel = 24, xp = 1950, giver = "Myrokos Silentform", giverNpc = 13085, turnIn = "Myrokos Silentform", turnInNpc = 13085, rewardsUnknown = true, kills = { { name = "Lord Tomas", npc = 266216 } }, objective = "Find Lord Tomas inside Durnholde Keep, in Hillsbrad Foothills, and kill him. Then, return to Myrokos Silentform." },
    { id = 96783, name = "A Way In", classes = "Rogue", level = 34, minLevel = 24, xp = 2700, giver = "Myrokos Silentform", giverNpc = 13085, turnIn = "Syndicate Footlocker", turnInNpc = -656157, rewardsUnknown = true, objective = "Steal a Syndicate uniform from Northfold Manor to infiltrate Stromgarde Keep." },
    { id = 96785, name = "Ain't No Telling", classes = "Rogue", level = 34, minLevel = 24, xp = 2700, giver = "Anastasia Miller", giverNpc = 266847, turnIn = "Anastasia Miller", turnInNpc = 266847, rewardsUnknown = true, loot = { { item = 275709, name = "Stolen Funds", from = {  } } }, objective = "Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal." },
    { id = 96784, name = "Master of Disguise", side = "Horde", classes = "Rogue", level = 34, minLevel = 24, xp = 2700, giver = "Syndicate Footlocker", giverNpc = -656157, turnIn = "Anastasia Miller", turnInNpc = 266847, rewardsUnknown = true, objective = "While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal." },
    { id = 96786, name = "The Syndicate Sting", classes = "Rogue", level = 34, minLevel = 24, xp = 3350, giver = "Anastasia Miller", giverNpc = 266847, turnIn = "Myrokos Silentform", turnInNpc = 13085, rewardsUnknown = true, loot = { { item = 275882, name = "Intercepted Shipment", from = {  } }, { item = 275706, name = "Syndicate Uniform", from = {  } } }, objective = "Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor." },
    { id = 96782, name = "Covert Extraction", classes = "Rogue", level = 36, minLevel = 24, xp = 2800, giver = "Myrokos Silentform", giverNpc = 13085, turnIn = "Myrokos Silentform", turnInNpc = 13085, rewardsUnknown = true, loot = { { item = 275635, name = "Blade of House Perenolde", from = {  } }, { item = 275636, name = "Royal Aegis of Perenolde", from = {  } } }, objective = "Find the Blade of House Perenolde and the Royal Aegis of Perenolde among the ruins of Alterac. Then, bring them to Myrokos Silentform." },
    { id = 96781, name = "What's the Big Idea?", classes = "Rogue", level = 36, minLevel = 24, xp = 2800, giver = "Myrokos Silentform", giverNpc = 13085, turnIn = "Myrokos Silentform", turnInNpc = 13085, rewardsUnknown = true, loot = { { item = 275482, name = "Barton's Scouting Report", from = {  } } }, objective = "Steal Barton's Scouting Report by pickpocketing it from him. Then, bring the report to Myrokos Silentform at Ravenholdt Manor." },
