    { id = 7602, name = "Flawless Fel Essence", classes = "Warlock", level = 55, minLevel = 50, xp = 5650, giver = "Impsy", chainStart = 7601, chainStartName = "What Niby Commands", giverNpc = 14470, chainGiver = "Niby the Almighty", chainGiverNpc = 14469, turnIn = "Impsy", turnInNpc = 14470, chainStep = 2, named = { { name = "Legashi Satyr", npc = 6200 } }, loot = { { item = 18624, name = "Flawless Fel Essence (Azshara)", from = { { name = "Legashi Blackguard" }, { name = "Legashi Hellraiser" } } }, { item = 18622, name = "Flawless Fel Essence (Jaedenar)", from = { { name = "Jaedenar Legionnaire", npc = 9862 } } }, { item = 18623, name = "Flawless Fel Essence (Dark Portal)", from = { { name = "Felguard Sentry", npc = 6011 } } } }, chain = { 7601 }, objective = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.\n\nThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.\n\nRecover the Flawless Fel Essences and return to Impsy in Felwood." },
    { id = 7603, name = "Kroshius' Infernal Core", classes = "Warlock", level = 55, minLevel = 50, xp = 7050, giver = "Impsy", chainStart = 7601, chainStartName = "What Niby Commands", giverNpc = 14470, chainGiver = "Niby the Almighty", chainGiverNpc = 14469, turnIn = "Niby the Almighty", turnInNpc = 14469, chainStep = 3, kills = { { name = "Kroshius", npc = 14467 } }, loot = { { item = 18625, name = "Kroshius' Infernal Core", from = { { name = "Kroshius", npc = 14467 } } } }, rewards = { 18762 }, chain = { 7601, 7602 }, objective = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.\n\nReturn Kroshius' Infernal Core to Niby the Almighty in Felwood." },
    { id = 8381, name = "Armaments of War", classes = "Mage / Warlock", level = 60, minLevel = 58, xp = 6600, giver = "Geologist Larksbane", chainStart = 8304, chainStartName = "Dearest Natalia", giverNpc = 15183, chainGiver = "Commander Mar'alith", chainGiverNpc = 15181, turnIn = "Geologist Larksbane", turnInNpc = 15183, chainStep = 5, rewards = { 20705, 20716 }, chain = { 8304, 8309, 8314, 8315 } },
