    { id = 7628, name = "Doomsday Candle", classes = "Warlock", level = 60, minLevel = 60, xp = 6600, giver = "Mor'zul Bloodbringer", chainStart = 7563, chainStartName = "Rage of Blood", giverNpc = 14436, chainGiver = "Mor'zul Bloodbringer", chainGiverNpc = 14436, turnIn = "Gorzeeki Wildeyes", turnInNpc = 14437, chainStep = 3, loot = { { item = 15416, name = "Black Dragonscale", from = { { name = "Chromatic Whelp" }, { name = "Onyxia's Elite Guard" } } } }, chain = { 7563, 7564 }, objective = "Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes." },
    { id = 7629, name = "Imp Delivery", classes = "Warlock", level = 60, minLevel = 60, xp = 6600, giver = "Gorzeeki Wildeyes", chainStart = 7623, chainStartName = "Lord Banehollow", giverNpc = 14437, chainGiver = "Gorzeeki Wildeyes", chainGiverNpc = 14437, turnIn = "Gorzeeki Wildeyes", turnInNpc = 14437, chainStep = 4, dungeon = "SCHOLOMANCE", kills = { { name = "J'eevee" } }, chain = { 7623, 7624, 7625 }, objective = "Bring the Imp in a Jar to the alchemy lab in the Scholomance. After the parchment is created, return the jar to Gorzeeki Wildeyes." },
    { id = 7583, name = "Suppression", classes = "Warlock", level = 60, minLevel = 60, xp = 6600, giver = "Daio the Decrepit", chainStart = 7581, chainStartName = "The Prison's Bindings", giverNpc = 14463, chainGiver = "Daio the Decrepit", chainGiverNpc = 14463, turnIn = "Daio the Decrepit", turnInNpc = 14463, chainStep = 2, named = { { name = "Doomguard Commander", npc = 12396 } }, loot = { { item = 18605, name = "Imprisoned Doomguard", from = { { name = "Imprisoned Doomguard", npc = -179644 } } } }, rewards = { 18602 }, chain = { 7581 }, objective = "Venture forth into the Tainted Scar and locate a Doomguard Commander.\n\nUse the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.\n\nShould you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar." },
    { id = 7581, name = "The Prison's Bindings", classes = "Warlock", level = 60, minLevel = 60, xp = 6600, giver = "Daio the Decrepit", giverNpc = 14463, turnIn = "Daio the Decrepit", turnInNpc = 14463, dungeon = "DM_EAST", named = { { name = "Wildspawn Satyr" } }, loot = { { item = 18603, name = "Satyr Blood", from = { { name = "Wildspawn Betrayer" }, { name = "Wildspawn Felsworn" } } } }, objective = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done." },
    { id = 7582, name = "The Prison's Casing", classes = "Warlock", level = 60, minLevel = 60, xp = 6600, giver = "Daio the Decrepit", giverNpc = 14463, turnIn = "Daio the Decrepit", turnInNpc = 14463, loot = { { item = 18604, name = "Tears of the Hederine", from = { { name = "Ridolus" }, { name = "Hederine Initiate", npc = 7461 } } } }, objective = "Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task." },
    { id = 7627, name = "Wheel of the Black March", classes = "Warlock", level = 60, minLevel = 60, xp = 6600, giver = "Mor'zul Bloodbringer", chainStart = 7563, chainStartName = "Rage of Blood", giverNpc = 14436, chainGiver = "Mor'zul Bloodbringer", chainGiverNpc = 14436, turnIn = "Gorzeeki Wildeyes", turnInNpc = 14437, chainStep = 3, dungeon = "BRD", loot = { { item = 14344, name = "Large Brilliant Shard", from = {  } }, { item = 11370, name = "Dark Iron Ore", from = { { name = "Dark Iron Deposit" } } } }, chain = { 7563, 7564 }, objective = "Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes." },
