    { id = 6002, name = "Body and Heart", side = "Horde", classes = "Druid", level = 10, minLevel = 10, xp = 840, giver = "Turak Runetotem", chainStart = 5922, chainStartName = "Moonglade", giverNpc = 3033, chainGiver = "Turak Runetotem", chainGiverNpc = 3033, turnIn = "Turak Runetotem", turnInNpc = 3033, chainStep = 4, kills = { { name = "Lunaclaw Spirit", npc = 12144 } }, chain = { 5922, 5930, 5932 }, objective = "Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Turak Runetotem in Thunder Bluff when you are done." },
