    { id = 6124, name = "Curing the Sick", side = "Alliance", classes = "Druid", level = 14, minLevel = 14, xp = 740, giver = "Alanndarian Nightsong", chainStart = 6121, chainStartName = "Lessons Anew", giverNpc = 3702, chainGiver = "Mathrengyl Bearwalker", chainGiverNpc = 4217, turnIn = "Dendrite Starblaze", turnInNpc = 11802, chainStep = 4, kills = { { name = "Sickly Deer", npc = 12298 } }, rewards = { 15866 }, chain = { 6121, 6122, 6123 }, objective = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them. Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins." },
    { id = 6129, name = "Curing the Sick", side = "Horde", classes = "Druid", level = 14, minLevel = 14, xp = 740, giver = "Tonga Runetotem", chainStart = 6126, chainStartName = "Lessons Anew", giverNpc = 3448, chainGiver = "Turak Runetotem", chainGiverNpc = 3033, turnIn = "Dendrite Starblaze", turnInNpc = 11802, chainStep = 4, kills = { { name = "Sickly Gazelle", npc = 12296 } }, rewards = { 15866 }, chain = { 6126, 6127, 6128 }, objective = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them. Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads." },
    { id = 6123, name = "Gathering the Cure", side = "Alliance", classes = "Druid", level = 14, minLevel = 14, xp = 740, giver = "Alanndarian Nightsong", chainStart = 6121, chainStartName = "Lessons Anew", giverNpc = 3702, chainGiver = "Mathrengyl Bearwalker", chainGiverNpc = 4217, turnIn = "Alanndarian Nightsong", turnInNpc = 3702, chainStep = 3, loot = { { item = 2449, name = "Earthroot", from = { { name = "Lasher Sproutling", npc = 275703 }, { name = "Wrathvine", npc = 276099 } } }, { item = 15851, name = "Lunar Fungus", from = { { name = "Lunar Fungal Bloom", npc = -177750 } } } }, chain = { 6121, 6122 }, objective = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve." },
